if (url.pathname === '/health') {
  return json(res, 200, {
    ok: true, engine: ENGINE, cli: !!engineBin, auth: hasCredentials(), skills: SKILLS.length,
    workshop: WORKSHOP_ENABLED,
    // Кому показывать пункт «Мастерская»: по умолчанию админу, при флаге — всем.
    workshop_all: WORKSHOP_ALL,
    sources: MCP_SOURCES.filter((x) => (process.env[x.env] || '').trim()).map((x) => x.key),
    dictation: await asrReachable(),
    ...(oauthTokenProblem.reason ? { authProblem: oauthTokenProblem.reason } : {}),
  })
}

if (['/api/skills', '/api/methods', '/api/knowledge', '/api/prompts',
     '/api/growth', '/api/sessions'].includes(url.pathname) && req.method === 'GET') {
  const gAuth = req.headers.authorization || ''
  if (!gAuth.startsWith('Bearer ')) return json(res, 401, { error: 'нужен токен пространства' })
  const gCfg = await fetchSettings(gAuth, safeCompany(req.headers['x-company-id']))
  if (gCfg.core_down) return json(res, 503, { error: CORE_DOWN })
  if (!gCfg.ok) return json(res, 403, { error: 'нет доступа к этому пространству' })
  req.agentCfg = gCfg
}

if (url.pathname === '/api/skills' && req.method === 'GET') {
  return json(res, 200, SKILLS.map(({ id, name, group, when }) => ({ id, name, group, when })))
}

if (url.pathname === '/api/knowledge' && req.method === 'GET') {
  // Личная карточка показывается только тому, чья она: её видно, когда запрос
  // пришёл с токеном пространства. Без токена ручка отдаёт общее знание, как и
  // раньше, — это состав агента, а не данные компании.
  // 🔴 Слой ОРГАНИЗАЦИИ — это её документы: учётная политика, договоры, правила
  // исключений. Раньше он уезжал по одному заголовку `X-Company-Id`, без токена:
  // «состав агента читается открыто» верно для общего слоя, но не для клиентского.
  // Без токена отдаём только знание пространства.
  // Членство подтверждено гейтом выше: `req.agentCfg.ok` истинно только когда
  // Ядро согласилось выдать настройки ИМЕННО этой организации спросившему.
  const kCompany = safeCompany(req.headers['x-company-id'])
  return json(res, 200, readKnowledge(kCompany, req.agentCfg?.user_id))
}

if (url.pathname === '/api/sessions' && req.method === 'GET') {
  // Свои вкладки, а не все в контейнере: чужие сеансы — это чужая работа, и знать
  // о ней «занято/свободно» человеку незачем, тем более что подключиться к ним он
  // теперь всё равно не может.
  const meId = req.agentCfg?.user_id
  let live = []
  try {
    live = execSync('tmux list-sessions -F "#{session_name} #{session_many_attached}"', { encoding: 'utf8' })
      .trim().split('\n').filter(Boolean)
      .map((l) => l.split(' '))
      .map(([name, many]) => ({ name, many: many === '1' }))
  } catch { /* сервера tmux нет — значит и сеансов нет */ }
  return json(res, 200, Array.from({ length: TABS }, (_, tab) => {
    const s = live.find((x) => x.name === sessionName(tab, meId))
    // `shared` — сеанс смотрят из нескольких окон. Это нормально, но объясняет
    // узкое поле справа: окно идёт по самому маленькому из них.
    return { tab, live: !!s, shared: !!s?.many }
  }))
}

if (url.pathname === '/api/prompts' && req.method === 'GET') {
  return json(res, 200, readPrompts(String(req.headers['x-company-id'] || '')))
}

if (url.pathname === '/api/reload' && req.method === 'POST') {
  // Пересчёт дёргает psql и python-скрипты минутами и глушит процесс целиком —
  // такое не может быть открытым: раньше ручку мог позвать кто угодно снаружи.
  const rAuth = req.headers.authorization || ''
  if (!rAuth.startsWith('Bearer ')) return json(res, 401, { error: 'нужен токен пространства' })
  const rCfg = await fetchSettings(rAuth, String(req.headers['x-company-id'] || ''))
  if (rCfg.core_down) return json(res, 503, { error: CORE_DOWN })
  if (!rCfg.can_manage) return json(res, 403, { error: 'Пересчёт запускает администратор пространства' })
  return handleReload(res)
}

if (req.method === 'GET' && !url.pathname.startsWith('/api')) {
  res.writeHead(302, { Location: APP_PATH })
  return res.end()
}

} catch (e) {
  if (!res.headersSent) json(res, 500, { error: e.message })
}
